solution.accumulate.zig:
const std = @import("std");

pub fn accumulate(comptime T: type, comptime U: type, allocator: std.mem.Allocator, items: []const T, operation: fn (T) U) ![]U {
    const result = try allocator.alloc(U, items.len);
    for (items, 0..) |item, i| result[i] = operation(item);
    return result;
}

tests.test_accumulate.zig:
const std = @import("std");
const t = std.testing;
const a = t.allocator;
const m = @import("accumulate.zig");

fn square(n: i32) i32 {
    return n * n;
}
fn halve(n: i32) f64 {
    return @as(f64, @floatFromInt(n)) / 2;
}
fn upper(c: u8) u8 {
    return std.ascii.toUpper(c);
}
test "empty, numbers, changed result type and characters" {
    const empty = try m.accumulate(i32, i32, a, &.{}, square);
    defer a.free(empty);
    try t.expectEqual(@as(usize, 0), empty.len);
    const numbers = try m.accumulate(i32, i32, a, &.{ 1, 2, 3, 4, 5 }, square);
    defer a.free(numbers);
    try t.expectEqualSlices(i32, &.{ 1, 4, 9, 16, 25 }, numbers);
    const halves = try m.accumulate(i32, f64, a, &.{ 1, 3, 5 }, halve);
    defer a.free(halves);
    try t.expectEqualSlices(f64, &.{ 0.5, 1.5, 2.5 }, halves);
    const text = try m.accumulate(u8, u8, a, "hello", upper);
    defer a.free(text);
    try t.expectEqualStrings("HELLO", text);
    const twice = try m.accumulate(i32, i32, a, numbers, square);
    defer a.free(twice);
    try t.expectEqualSlices(i32, &.{ 1, 16, 81, 256, 625 }, twice);
}
